    AND l.itemid IN (
        51221, -- Hematocrit
        51222, -- Hemoglobin
        51248, -- MCH
        51249, -- MCHC
        51250, -- MCV
        51265, -- Platelet Count
        51279, -- RBC
        51277, -- RDW
        52159,
        51301  -- WBC
    )
    AND l.valuenum IS NOT NULL
    AND l.valuenum != 0
    GROUP BY
        l.subject_id,
        l.charttime
),

ranked_panels AS (
    SELECT
        subject_id,
        charttime,
        ROW_NUMBER() OVER (
            PARTITION BY subject_id
            ORDER BY charttime DESC
        ) AS rn
    FROM cbc_panels
)

SELECT
    l.subject_id,
    l.charttime,
    li.label,
    l.valuenum,
    l.valueuom,
    l.ref_range_lower,
    l.ref_range_upper,
    l.flag

FROM `physionet-data.mimiciv_3_1_hosp.labevents` l

LEFT JOIN `physionet-data.mimiciv_3_1_hosp.d_labitems` li
    ON l.itemid = li.itemid

INNER JOIN ranked_panels p
    ON l.subject_id = p.subject_id
    AND l.charttime = p.charttime
    AND p.rn = 1

WHERE l.itemid IN (
    51221,
    51222,
    51248,
    51249,
    51250,
    51265,
    51279,
    51277,
    52159,
    51301
)
AND l.valuenum IS NOT NULL
AND l.valuenum != 0

ORDER BY
    l.subject_id,
    l.charttime,
    li.label;